WITH metrics AS (SELECT *, NTILE(3) OVER w_running AS balance_bucket, CUME_DIST() OVER (PARTITION BY account_type ORDER BY balance DESC NULLS LAST) AS balance_cume_dist, SUM(balance) OVER (PARTITION BY status) AS status_sum_balance, ROW_NUMBER() OVER (ORDER BY balance, id) AS seq_no FROM accounts WINDOW w_running AS (PARTITION BY DATE_TRUNC('YEAR', opened_date) ORDER BY balance DESC, id)) SELECT s.id, s.customer_id, s.opened_date, s.status, s.balance_bucket, s.balance_cume_dist, s.status_sum_balance, s.seq_no, (SELECT SUM(o2.discount) FROM orders o2 WHERE o2.customer_id = s.customer_id) AS sum_order_discount FROM metrics s ORDER BY balance_cume_dist DESC NULLS FIRST;
